1	// Command chainledger is the 链上数据治理与血缘工作台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9	
10		"github.com/asdhoaiqqq/chainledger-governance/chainledger"
11	)
12	
13	func main() {
14		os.Exit(run(os.Args[1:]))
15	}
16	
17	// run dispatches the command and returns the process exit code. Keeping the
18	// exit code out of main makes the CLI testable without spawning a subprocess.
19	func run(args []string) int {
20		command := "demo"
21		if len(args) > 0 {
22			command = args[0]
23		}
24		switch command {
25		case "demo":
26			runDemo()
27			return 0
28		case "version":
29			fmt.Println("chainledger 0.2.0")
30			return 0
31		case "preview":
32			return runBatch(args[1:], false)
33		case "apply":
34			return runBatch(args[1:], true)
35		case "help", "-h", "--help":
36			usage()
37			return 0
38		default:
39			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
40			usage()
41			return 2
42		}
43	}
44	
45	func usage() {
46		fmt.Print(`usage: chainledger <command> [arguments]
47	
48	commands:
49	  demo                        run the built-in lineage demo
50	  version                     print the version
51	  preview <graph> <plan>      validate the batch and print the report without
52	                              modifying the graph file
53	  apply <graph> <plan>        validate the batch, apply it to the graph file,
54	                              and print the report
55	  help                        show this help
56	
57	The graph file is JSON:
58	  {"datasets": [{"name": "A", "upstreams": []}, ...]}
59	
60	The plan file is JSON:
61	  {"changes": [{"name": "A", "upstreams": ["B"]}, ...]}
62	
63	A batch registers new datasets or replaces every direct upstream of an
64	existing dataset with the listed upstreams. An empty upstream list makes the
65	dataset a root. Datasets not mentioned in the plan keep their upstreams.
66	New datasets may reference each other regardless of plan order; the final
67	graph must be acyclic and every upstream must resolve to a dataset in the
68	final graph. Preview and apply produce the same report for the same inputs.
69	`)
70	}
71	
72	// runBatch implements preview (apply=false) and apply (apply=true). It reads
73	// the graph and plan JSON files, validates them, prints the report to stdout,
74	// and — only for apply — writes the final graph back to the graph file. Any
75	// failure is reported on stderr with a non-zero exit code; on failure the graph
76	// file is left untouched.
77	func runBatch(args []string, apply bool) int {
78		if len(args) != 2 {
79			fmt.Fprintf(os.Stderr, "usage: chainledger %s <graph.json> <plan.json>\n", verb(apply))
80			return 2
81		}
82		graphPath := args[0]
83		planPath := args[1]
84	
85		graphData, err := os.ReadFile(graphPath)
86		if err != nil {
87			fmt.Fprintf(os.Stderr, "error: cannot read graph file %q: %v\n", graphPath, err)
88			return 1
89		}
90		graph, err := chainledger.UnmarshalGraphFile(graphData)
91		if err != nil {
92			fmt.Fprintf(os.Stderr, "error: invalid graph file %q: %v\n", graphPath, err)
93			return 1
94		}
95	
96		planData, err := os.ReadFile(planPath)
97		if err != nil {
98			fmt.Fprintf(os.Stderr, "error: cannot read plan file %q: %v\n", planPath, err)
99			return 1
100		}
101		plan, err := chainledger.UnmarshalPlan(planData)
102		if err != nil {
103			fmt.Fprintf(os.Stderr, "error: invalid plan file %q: %v\n", planPath, err)
104			return 1
105		}
106	
107		var report *chainledger.BatchReport
108		if apply {
109			report, err = chainledger.ApplyBatch(graph, plan)
110		} else {
111			report, err = chainledger.PreviewBatch(graph, plan)
112		}
113		if err != nil {
114			fmt.Fprintf(os.Stderr, "error: %v\n", err)
115			return 1
116		}
117	
118		if apply {
119			out, err := chainledger.MarshalGraphFile(graph)
120			if err != nil {
121				fmt.Fprintf(os.Stderr, "error: cannot serialize final graph: %v\n", err)
122				return 1
123			}
124			if err := atomicWrite(graphPath, out); err != nil {
125				fmt.Fprintf(os.Stderr, "error: cannot write graph file %q: %v\n", graphPath, err)
126				return 1
127			}
128		}
129	
130		enc := json.NewEncoder(os.Stdout)
131		enc.SetIndent("", "  ")
132		if err := enc.Encode(report); err != nil {
133			fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
134			return 1
135		}
136		return 0
137	}
138	
139	func verb(apply bool) string {
140		if apply {
141			return "apply"
142		}
143		return "preview"
144	}
145	
146	// atomicWrite writes data to a temporary file in the same directory as path
147	// and renames it into place, so a write failure never leaves a partially
148	// written graph file: the original is preserved.
149	func atomicWrite(path string, data []byte) error {
150		dir := filepath.Dir(path)
151		tmp, err := os.CreateTemp(dir, ".chainledger-*")
152		if err != nil {
153			return err
154		}
155		tmpName := tmp.Name()
156		committed := false
157		defer func() {
158			if !committed {
159				os.Remove(tmpName)
160			}
161		}()
162		if _, err := tmp.Write(data); err != nil {
163			tmp.Close()
164			return err
165		}
166		if err := tmp.Close(); err != nil {
167			return err
168		}
169		if err := os.Rename(tmpName, path); err != nil {
170			return err
171		}
172		committed = true
173		return nil
174	}
175	
176	func runDemo() {
177		graph := map[string]*chainledger.Lineage{}
178		register := func(dataset chainledger.Dataset, parents []string) {
179			if err := chainledger.Register(graph, dataset, parents); err != nil {
180				fmt.Printf("dataset=%s refused: %v\n", dataset.Name, err)
181				return
182			}
183			fmt.Printf("dataset=%s registered parents=%v\n", dataset.Name, parents)
184		}
185		register(chainledger.Dataset{Name: "raw-blocks", SchemaVersion: 3}, nil)
186		register(chainledger.Dataset{Name: "transfers", SchemaVersion: 2}, []string{"raw-blocks"})
187		register(chainledger.Dataset{Name: "wallet-daily", SchemaVersion: 1}, []string{"transfers"})
188		register(chainledger.Dataset{Name: "raw-blocks", SchemaVersion: 4}, []string{"wallet-daily"})
189		fmt.Println("roots:", chainledger.Roots(graph))
190		fmt.Printf("datasets=%d\n", len(graph))
191	}
192

