338		graph := map[string]*Lineage{}
339		mustRegister(t, graph, "zeta")
340		mustRegister(t, graph, "alpha")
341		mustRegister(t, graph, "mid", "alpha")
342		mustRegister(t, graph, "beta")
343		want := []string{"alpha", "beta", "zeta"}
344		for i := 0; i < 5; i++ {
