224		}
225		if len(report.ChangedDatasets) != 0 || len(report.AddedRelations) != 0 ||
226			len(report.RemovedRelations) != 0 || len(report.AffectedDownstreams) != 0 {
227			t.Errorf("empty plan produced non-empty diff: %+v", report)
228		}
229	
230		// Apply once, then again: the second apply is a no-op.
231		if _, err := ApplyBatch(graph, plan); err != nil {
232			t.Fatalf("first ApplyBatch unexpected error: %v", err)
233		}
234		snapshot := dump(graph)
235		report, err = ApplyBatch(graph, plan)
236		if err != nil {
237			t.Fatalf("second ApplyBatch unexpected error: %v", err)
238		}
239		if got := dump(graph); got != snapshot {
240			t.Fatalf("re-apply mutated graph:\n got %s\nwant %s", got, snapshot)
241		}
242		if len(report.ChangedDatasets) != 0 || len(report.AddedRelations) != 0 ||
243			len(report.RemovedRelations) != 0 || len(report.AffectedDownstreams) != 0 {
244			t.Errorf("re-apply produced non-empty diff: %+v", report)
245		}
246	}
247	
248	// TestBatchOrderAndDuplicateUpstreamInvariance verifies that changing only the
249	// input order or repeating an upstream does not count as a change.
250	func TestBatchOrderAndDuplicateUpstreamInvariance(t *testing.T) {
251		graph := buildGraph(t, P("A"), P("B"), P("C", "A", "B"))
252		// Same set, different order and duplicates.
253		plan := planOf(change("C", "B", "A", "A", "B"))
254		report, err := PreviewBatch(graph, plan)
255		if err != nil {
256			t.Fatalf("PreviewBatch unexpected error: %v", err)
257		}
258		if len(report.ChangedDatasets) != 0 {
259			t.Errorf("order/duplicate-only change counted as a real change: %v", report.ChangedDatasets)
260		}
261		if len(report.AddedRelations) != 0 || len(report.RemovedRelations) != 0 {
262			t.Errorf("order/duplicate-only change produced a relation diff: +%v -%v", report.AddedRelations, report.RemovedRelations)
263		}
264	}
