315	// TestBatchRejectsInvalidOriginalGraph verifies that a plan cannot paper over
316	// pre-existing corruption in the input graph.
317	func TestBatchRejectsInvalidOriginalGraph(t *testing.T) {
318		empty := planOf()
319	
320		t.Run("nil node", func(t *testing.T) {
321			graph := map[string]*Lineage{"A": nil}
