356	// TestBatchEmptyGraphAllowsNewDatasets verifies that an empty graph accepts a
357	// batch that registers new datasets.
358	func TestBatchEmptyGraphAllowsNewDatasets(t *testing.T) {
359		graph := map[string]*Lineage{}
