		visited[current] = true
		parents := adj[current]
		if len(parents) == 0 {
			roots = append(roots, current)
			return
		}
		for _, parent := range parents {
			walk(parent)
		}
	}
	walk(node)
	sort.Strings(roots)
	return orEmptyStrings(roots)
}

func orEmptyStrings(s []string) []string {
